'use strict';
const {Game,TRAITS,CAST,DIRS}=House;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let game=null,mode='solo',floor=0,hitAreas=[],audioCtx=null,sound=false,aiTimer=null,showedResult=false;
const SAVE='house-v03-save';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,disabled=false,cls='')=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
function saved(){try{const s=JSON.parse(localStorage.getItem(SAVE));return s?.version===1?s:null}catch{return null}}
function persist(){try{localStorage.setItem(SAVE,JSON.stringify(game.s))}catch{document.querySelector('#saveStatus')?.replaceChildren('浏览器未允许存档')}}
function openModal(html,closeable=true){modal.innerHTML=html;modal.dataset.closable=String(closeable);if(!modal.open)modal.showModal();const b=modal.querySelector('button');b?.focus()}
function closeModal(){modal.close();if(game){game.s.report=null;persist();scheduleAI()}}
modal.addEventListener('cancel',e=>{if(modal.dataset.closable==='false')e.preventDefault();else{game&&(game.s.report=null);game&&persist();scheduleAI()}});
function tone(kind='move'){if(!sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=kind==='haunt'?'sawtooth':'sine';o.frequency.setValueAtTime(kind==='haunt'?85:kind==='dice'?420:190,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='haunt'?42:80,audioCtx.currentTime+.3);g.gain.setValueAtTime(.05,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.5);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.5)}catch{sound=false}}
function setup(){clearTimeout(aiTimer);game=null;showedResult=false;app.className='';app.innerHTML=`<section class="start"><div class="setup"><div class="eyebrow">HOUSE ON THE HILL · PLAYABLE PROTOTYPE</div><h1>山中小屋</h1><p class="intro">门已打开。<br>而你们之中，有人正在等待这一刻。</p><div class="setupbox"><h3>开始一场降魂仪式</h3><div class="modes"><button data-action="mode:solo" class="${mode==='solo'?'on':''}">单人探索<small>控制英雄队伍 · 敌方自动行动</small></button><button data-action="mode:local" class="${mode==='local'?'on':''}">本地多人<small>3–6 人 · 同一设备轮流操作</small></button></div><div class="formrow"><label>探索者人数<select id="count" ${mode==='solo'?'disabled':''}>${[3,4,5,6].map(n=>`<option ${n===4?'selected':''}>${n}</option>`).join('')}</select></label><label>地图种子<input id="seed" value="HOUSE-03" maxlength="30" aria-label="地图随机种子"></label></div><div class="startbuttons">${btn('进入小屋','start',false,'primary')}${btn('直接测试作祟','quick')}${saved()?btn('继续上次对局','resume'):''}</div><p class="note">v0.3 · 首个玩法切片 / #2 降魂仪式<br>概念图沿用策划案；棋盘为等距规则原型。完整 HD-2D 场景与其他剧本尚未实现。</p>${btn('操作与规则简化说明','help',false,'small')}</div></div><div class="scene-caption"><div class="eyebrow">THE HOUSE REMEMBERS</div><span>探索 / 预兆 / 背叛</span></div></section>`}
function help(){openModal(`<div class="eyebrow">PLAY GUIDE</div><h2>活着离开这座小屋</h2><div class="helpgrid"><div><h3>01 · 探索</h3><p>点击相邻房间移动；点击虚线门或方向按钮发现房间。<kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> 对应北西南东。抽到卡牌后移动归零，仍可使用道具。</p></div><div><h3>02 · 预兆</h3><p>回合末掷 6 颗 0/1/2 骰，总和严格小于预兆数时触发作祟。<kbd>空格</kbd>结束回合。楼层按钮只切换视图；跨层移动需站在楼梯或平台上。</p></div><div><h3>03 · 降魂仪式</h3><p>最低理智者成为叛徒。知识或理智 ≥ 4，英雄成功 +1、叛徒 +2；先到 3 点控制幽灵。仪式每人每回合一次，此时禁止攻击。</p></div><div><h3>04 · 最终目标</h3><p>英雄召唤：知识 ≥ 4 找遗骸，送至安葬点，6 轮内安葬。叛徒召唤：英雄同房以理智对抗幽灵 4 骰，成功驱散 3 次获胜。全部英雄死亡则叛徒胜。</p></div></div><h3>此 Demo 的规则适配</h3><p class="helper">依据 v0.3 第 29、31.2、34 节，固定测试 #2 的结构；并非官方剧本的逐条复刻。使用 6 名自定义探索者、24 张简化房间、6 类事件、6 件道具和 13 个无独立能力的预兆。地下平台与大楼梯直接连接；仪式可在任意房间举行；伤害自动分配至余量较多的同类属性；不实现偷取、隐藏叛徒、完整房间特例及其他 99 个剧本。单人模式探索阶段控制全队，作祟后叛徒由系统接管。多人交接遮屏用于共享设备礼让隐私。</p><p class="helper">地图种子控制随机序列；同样操作可复现结果。对局自动保存在当前浏览器。音效为合成提示音，可随时关闭。</p><div class="dialogactions">${btn('明白了','close',false,'primary')}</div>`)}
function begin(quick=false){const opt={mode,count:document.querySelector('#count').value,seed:document.querySelector('#seed').value.trim()||'HOUSE-03',quick};game=new Game(opt);floor=game.roomNow.f;render();persist();if(game.s.report)report();else if(mode==='local')handoff();}
function handoff(){let p=game.p;openModal(`<div class="handoff"><div class="eyebrow">PASS THE DEVICE</div><div class="token" style="color:${p.color}">${p.id+1}</div><h2>请交给 ${p.name}</h2><p>其余玩家请暂时移开视线。<br>准备好后查看你的回合与阵营说明。</p>${btn('我是 '+p.name+'，开始回合','brief',false,'primary')}</div>`,false)}
function brief(){const s=game.s,p=game.p;let title=s.phase==='explore'?'你是探索者':p.team==='hero'?'你属于英雄阵营':'你是叛徒';let text=s.phase==='explore'?'共同探索，积累道具。作祟前没有固定阵营，每个人都可能背叛。':p.team==='hero'?'抢先完成仪式，找到并安葬遗骸。如果叛徒夺得幽灵，就靠近它并完成三次驱散。':'抢夺仪式控制权。成功检定可获得 2 点进度；若英雄先召唤幽灵，攻击遗骸携带者，拖到倒计时结束。';openModal(`<div class="eyebrow">${esc(game.p.name)} · PRIVATE BRIEFING</div><h2>${title}</h2><p>${text}</p><div class="dialogactions">${btn('返回棋盘','close',false,'primary')}</div>`,false)}
function report(){const r=game.s.report;if(!r)return;const haunt=['降魂仪式','幽灵回应了英雄','幽灵回应了叛徒'].includes(r.title);if(haunt)tone('haunt');openModal(`${haunt?'<img src="ritual.png" alt="策划案中的降魂仪式概念图">':''}<div class="eyebrow">${haunt?'HAUNT REVEAL':'HOUSE CHRONICLE'}</div><h2>${esc(r.title)}</h2><p>${esc(r.text)}</p>${diceHTML()}<div class="dialogactions">${btn('继续',game.s.mode==='local'&&r.title==='降魂仪式'?'revealDone':'close',false,'primary')}</div>`,false)}
function diceHTML(){return game.s.dice.length?`<div class="dice" aria-label="最近一次骰子结果 ${game.s.dice.join(',')}">${game.s.dice.map(n=>`<span class="die">${n===0?'—':n===1?'•':'••'}</span>`).join('')}</div>`:''}
function objectiveHTML(){const s=game.s;if(s.phase==='explore')return`<div class="objective">探索未知房间<p>寻找道具，警惕预兆。点击房间旁的虚线框探索。</p></div><div class="objective">下一次转折<p>抽到预兆后，回合末自动进行作祟检定。</p></div>`;if(s.phase==='ritual')return`<div class="objective">争夺幽灵控制权<p>知识 / 理智 ≥ 4。每回合一次。</p></div>${[['英雄',s.heroProgress],['叛徒',s.traitorProgress]].map(([t,n])=>`<div class="helper">${t}仪式 <strong>${n} / 3</strong></div><div class="meter"><i style="width:${Math.min(100,n/3*100)}%"></i></div>`).join('')}<p class="helper">英雄成功 +1 · 叛徒成功 +2<br>首次召唤前，双方不可攻击。</p>`;if(s.phase==='burial'){const corpse=s.rooms.find(r=>r.id===s.corpseRoom),burial=s.rooms.find(r=>r.id===s.burialRoom);return`<div class="objective">${s.carrier===null?'Ⅰ · 找到遗骸':'Ⅰ · 遗骸已找到'}<p>${s.carrier===null?esc(corpse.name)+' · 知识检定 ≥ 4':'由 '+esc(s.players[s.carrier].name)+' 携带'}</p></div><div class="objective">Ⅱ · 运送并安葬<p>前往${esc(burial.name)}，执行安葬。</p></div><span class="badge">剩余 ${s.countdown} 轮</span><p class="helper" style="margin-top:12px">叛徒：击倒英雄或阻止安葬直到时限结束。</p>`}if(s.phase==='collapse')return`<div class="objective">驱散失控的幽灵<p>同房理智攻击，胜过幽灵 4 骰防御。每回合一次。</p></div><div class="helper">驱散成功 <strong>${s.ghost.hits} / 3</strong></div><div class="meter"><i style="width:${s.ghost.hits/3*100}%"></i></div><div class="objective">房屋正在崩塌<p>每轮一间末端房间坍塌，幽灵自动追击英雄。</p></div>`;return`<div class="objective">${s.result.team==='hero'?'英雄':'叛徒'}获胜<p>${esc(s.result.reason)}</p></div>`}
function render(){let s=game.s,p=game.p,r=game.roomNow;const locked=!p.alive||!!s.result||(s.mode==='solo'&&p.team==='traitor');const phase={explore:'探索阶段',ritual:'降魂仪式',burial:'寻找与安葬',collapse:'房屋崩塌',end:'对局结束'}[s.phase];app.className=s.phase!=='explore'?'haunting':'';app.innerHTML=`<header class="topbar"><div><span class="brand">山中小屋</span> <span class="eyebrow">/ 降魂仪式</span></div><div class="toptools"><span class="badge">${s.mode==='solo'?'单人 · 系统敌方':'本地 '+s.players.length+' 人'}</span><span id="saveStatus" class="helper">自动存档</span>${btn(sound?'声音 开':'声音 关','sound',false,'small')}${btn('规则','help',false,'small')}${btn('菜单','menu',false,'small')}</div></header><div class="game"><aside class="sidebar"><div class="section"><h3>探索队伍 <span class="muted">${s.players.filter(p=>p.alive).length}/${s.players.length}</span></h3>${s.players.map(q=>`<div class="player ${q.id===s.active?'active':''} ${!q.alive?'dead':''}"><div class="token" style="color:${q.color}">${q.id+1}</div><div><div class="name">${q.name}${q.id===s.active?' · 当前':''}</div><small>${!q.alive?'已倒下':q.team==='explorer'?q.role:q.team==='traitor'?'叛徒'+(s.mode==='solo'?' · 自动':''):'英雄'} · ${esc(s.rooms.find(r=>r.id===q.room).name)}</small></div></div>`).join('')}</div><div class="section"><h3>${p.name}的属性</h3>${TRAITS.map((t,i)=>`<div class="trait"><span>${t} <strong>${game.val(p,i)}</strong></span><span class="track">${p.tracks[i].map((n,j)=>`<i class="${p.idx[i]===j?'current':''}">${n}</i>`).join('')}</span></div>`).join('')}<p class="helper">属性变化按格移动；高亮为当前位置。</p></div><h3>随身物品 <span class="muted">${p.items.length}</span></h3><div class="inventory">${p.items.length?p.items.map(i=>`<div class="item"><span title="${esc(i.desc)}">${esc(i.name)}</span>${['heal','calm','speed'].includes(i.type)?btn('使用','use:'+i.id,locked||p.used.includes(i.id),'small'):''}</div>`).join(''):'<span class="muted">尚未获得物品</span>'}</div>${p.items.some(i=>i.type!=='omen')?'<div style="margin-top:15px">'+btn('同房交换','trade',locked,'small')+'</div>':''}</aside><section class="center"><div class="maphead"><div><div class="eyebrow">ROUND ${String(s.round).padStart(2,'0')} / ${phase}</div><div class="floors" style="margin-top:9px">${[[-1,'地下'],[0,'一层'],[1,'二层']].map(([f,n])=>btn(n,'floor:'+f,false,'small '+(floor===f?'on':''))).join('')}</div></div><div class="helper">${s.rooms.length} 间已发现<br>${btn('定位当前角色','focus',false,'small')}</div></div><div class="mapwrap"><canvas id="board" role="img" aria-label="交互房间地图。亦可使用下方方向按钮移动。"></canvas><div class="maplegend">◇ 当前房间　＋ 未探索门　◎ 目标　✧ 幽灵</div></div><div class="maphint" id="maphint">${locked?(s.result?'对局结束，可导出日志进行复盘。':!p.alive?'角色已倒下，请结束回合。':'敌方正在行动…'):'点击相邻房间移动，点击虚线门探索。'}</div><div class="actionbar"><div class="roomline"><div><h3>${esc(r.name)}</h3><small>${['地下层','一层','二层'][r.f+1]} · ${p.name}的回合${s.carrier===p.id?' · 携带遗骸':''}</small></div><span class="badge">移动 ${s.moves} / ${game.val(p,1)}</span></div><div class="actions">${game.exits().map(e=>btn(['↑ 北','→ 东','↓ 南','← 西'][e.d]+(e.target?'':' · 探索'),'move:'+e.d,locked||!e.open||s.moves<game.cost())).join('')}${game.neighbors(p.room).filter(n=>n.f!==r.f).map(n=>btn(n.f===1?'上楼':'下楼 / 返回楼梯','room:'+n.id,locked||s.moves<game.cost())).join('')}${s.phase==='ritual'?btn('知识仪式','task:2',locked||s.taskUsed)+btn('理智仪式','task:3',locked||s.taskUsed):''}${s.phase==='burial'&&p.team==='hero'&&((s.carrier===null&&s.corpseRoom===p.room)||(s.carrier===p.id&&s.burialRoom===p.room))?btn(s.carrier===p.id?'安葬遗骸':'寻找遗骸','task:2',locked||s.taskUsed,false):''}${s.phase==='collapse'&&p.team==='hero'&&s.ghost.room===p.room?btn('驱散幽灵','attack:ghost',locked||s.attackUsed,'danger'):''}${['burial','collapse'].includes(s.phase)?s.players.filter(t=>t.alive&&t.team!==p.team&&t.room===p.room).map(t=>btn('攻击 '+t.name,'attack:'+t.id,locked||s.attackUsed,'danger')).join(''):''}${r.loot?.length?btn('拾取遗落物品','pickup',locked):''}</div><div class="endrow"><span class="helper">${s.drawnOmen&&s.phase==='explore'?'结束回合时进行作祟检定':s.taskUsed?'本回合已尝试任务检定':s.moves===0?'移动已用尽，可使用道具或结束回合':'离开当前房间消耗 '+game.cost()+' 移动力'}</span>${btn('结束回合　→','end',!!s.result||(s.mode==='solo'&&p.team==='traitor'),'primary')}</div></div></section><aside class="sidebar rightbar"><div class="section"><div class="eyebrow">CURRENT OBJECTIVE</div><h3 style="margin-top:8px">${phase}</h3>${objectiveHTML()}</div><div class="section"><h3>预兆 <span style="color:var(--gold)">${s.omen} / 13</span></h3><div class="omenrow">${Array.from({length:13},(_,i)=>`<span class="${i<s.omen?'lit':''}"></span>`).join('')}</div><p class="helper">${s.phase==='explore'?'6 骰总和 < 预兆数 → 作祟':'作祟已触发，预兆不再改变阶段'}</p>${diceHTML()}</div><div><h3>房屋纪事</h3><div class="logs">${s.logs.slice(-22).reverse().map(l=>`<div class="log"><em>第 ${l.round} 轮</em><br>${esc(l.msg)}</div>`).join('')}</div><div style="margin-top:12px">${btn('导出复盘日志','export',false,'small')}</div></div></aside></div>`;drawMap();if(s.result&&!showedResult){showedResult=true;resultDialog()}}
function drawMap(){let canvas=document.querySelector('#board');if(!canvas||!game)return;const box=canvas.parentElement.getBoundingClientRect();const W=box.width,H=box.height,dpr=window.devicePixelRatio||1;canvas.width=W*dpr;canvas.height=H*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);let s=game.s,rooms=s.rooms.filter(r=>r.f===floor);let xs=rooms.map(r=>r.x),ys=rooms.map(r=>r.y);let candidates=[];if(game.roomNow.f===floor)for(const e of game.exits())if(e.open&&!e.target){const[dX,dY]=DIRS[e.d];candidates.push({x:game.roomNow.x+dX,y:game.roomNow.y+dY,d:e.d});xs.push(game.roomNow.x+dX);ys.push(game.roomNow.y+dY)}let coords=[...rooms,...candidates],us=coords.map(r=>r.x-r.y),vs=coords.map(r=>r.x+r.y),u0=(Math.max(...us)+Math.min(...us))/2,v0=(Math.max(...vs)+Math.min(...vs))/2;let tile=Math.min(112,(W-95)/(Math.max(...us)-Math.min(...us)+2),(H-90)/((Math.max(...vs)-Math.min(...vs)+2)*.52));tile=Math.max(26,tile);const pos=(x,y)=>[W/2+(x-y-u0)*tile,H/2+(x+y-v0)*tile*.52-5];hitAreas=[];function poly(points,fill,stroke){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}function diamond(x,y,size=1){return[[x,y-tile*.45*size],[x+tile*.86*size,y],[x,y+tile*.45*size],[x-tile*.86*size,y]]}c.lineWidth=1;
 for(const r of rooms){const [x,y]=pos(r.x,r.y);for(const n of game.neighbors(r.id).filter(n=>n.f===floor)){const[a,b]=pos(n.x,n.y);c.strokeStyle='#68775b';c.lineWidth=5;c.beginPath();c.moveTo(x,y);c.lineTo(a,b);c.stroke()}}
 for(const r of [...rooms].sort((a,b)=>a.x+a.y-b.x-b.y)){let[x,y]=pos(r.x,r.y);const active=r.id===game.p.room,adj=game.neighbors(game.p.room).some(n=>n.id===r.id);const obj=(s.phase==='burial'&&(r.id===s.burialRoom||(s.carrier===null&&r.id===s.corpseRoom)));poly([[x-tile*.86,y],[x,y+tile*.45],[x+tile*.86,y],[x+tile*.86,y+12],[x,y+tile*.45+12],[x-tile*.86,y+12]],'#131b16','#414a3b');c.lineWidth=active?2:1;poly(diamond(x,y),r.collapsed?'#25211e':active?'#56614a':adj?'#354b3b':'#26382d',r.collapsed?'#8d5147':active?'#e8d49a':obj?'#a8dfd6':'#637459');if(!r.collapsed){c.globalAlpha=.15;poly(diamond(x,y,.78),null,'#dcc987');c.globalAlpha=1;for(const d of r.doors){const[dx,dy]=DIRS[d];const[a,b]=pos(r.x+dx*.47,r.y+dy*.47);c.fillStyle=adj||active?'#dbbf81':'#78836b';c.fillRect(a-3,b-2,6,4)}}c.textAlign='center';c.fillStyle=r.collapsed?'#b28779':'#e4e5cd';c.font=`${Math.max(12,Math.min(14,tile*.19))}px system-ui`;c.fillText(r.collapsed?'× '+r.name:r.name,x,y+tile*.28);if(obj){c.fillStyle='#a7e9e1';c.font='18px system-ui';c.fillText('◎',x,y-tile*.20)}let ps=s.players.filter(p=>p.room===r.id&&p.alive);ps.forEach((p,i)=>{let px=x+(i-(ps.length-1)/2)*17,py=y-7;c.shadowColor=p.color;c.shadowBlur=p.id===s.active?12:0;c.fillStyle=p.color;c.beginPath();c.arc(px,py,8,0,Math.PI*2);c.fill();c.shadowBlur=0;c.fillStyle='#101713';c.font='bold 11px system-ui';c.fillText(p.id+1,px,py+4)});if(s.ghost?.room===r.id){c.fillStyle='#a7edf2';c.shadowColor='#8ddfee';c.shadowBlur=16;c.font='25px Georgia';c.fillText('✧',x+tile*.4,y-10);c.shadowBlur=0}hitAreas.push({x,y,tw:tile*.86,th:tile*.45,room:r.id});}
 for(const r of candidates){const[x,y]=pos(r.x,r.y);c.setLineDash([4,6]);c.lineWidth=1;poly(diamond(x,y,.75),'#20322555','#9caa7c');c.setLineDash([]);c.fillStyle='#c6d1ac';c.font='22px system-ui';c.textAlign='center';c.fillText('+',x,y+2);c.font='12px system-ui';c.fillText('探索',x,y+20);hitAreas.unshift({x,y,tw:tile*.66,th:tile*.4,d:r.d});}
 canvas.onclick=e=>{if(modal.open)return;const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;const h=hitAreas.find(a=>Math.abs(x-a.x)/a.tw+Math.abs(y-a.y)/a.th<1);if(h){if(h.d!==undefined)act('move:'+h.d);else if(h.room!==game.p.room){if(!game.neighbors(game.p.room).some(r=>r.id===h.room)){document.querySelector('#maphint').textContent='只能移动到相邻且门相通的房间。';return}act('room:'+h.room)}}};}
function resultDialog(){let r=game.s.result;openModal(`<img src="ritual.png" alt="降魂仪式概念图"><div class="eyebrow">THE NIGHT ENDS</div><h2 class="result-title">${r.team==='hero'?'英雄生还':'小屋吞噬了一切'}</h2><p>${esc(r.reason)}</p><p>历经 ${r.round} 轮 · ${game.s.rooms.length} 间房 · ${game.s.omen} 个预兆</p><div class="dialogactions">${btn('查看棋局','close')}${btn('导出日志','export')}${btn('新对局','new',false,'primary')}</div>`,false)}
function scheduleAI(){clearTimeout(aiTimer);if(game&&!modal.open&&!game.s.result&&game.s.mode==='solo'&&game.p.team==='traitor'){aiTimer=setTimeout(()=>{if(!game||modal.open)return;game.aiTurn();floor=game.roomNow.f;persist();render();if(game.s.report&&!game.s.result)report();scheduleAI()},800)}}
function exportLog(){let s=game.s;const obj={prototype:'v0.3-VS1',seed:s.seed,mode:s.mode,result:s.result,round:s.round,actions:s.actions,testStart:s.testStart,logs:s.logs,state:s};const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='house-demo-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function act(action){const [type,...bits]=action.split(':'),arg=bits.join(':');if(type==='mode'){mode=arg;setup();return}if(type==='start'||type==='quick'){begin(type==='quick');return}if(type==='help'){help();return}if(type==='close'){closeModal();return}if(type==='resume'){const s=saved();if(!s)return;game=new Game({},s);mode=s.mode;floor=game.roomNow.f;render();if(s.report)report();else if(s.mode==='local'&&!s.result)handoff();scheduleAI();return}if(type==='brief'){brief();return}if(type==='revealDone'){game.s.report=null;persist();handoff();return}if(type==='new'){modal.close();setup();return}if(!game)return;if(type==='menu'){openModal(`<h2>暂停探索</h2><p>进度已保存在当前浏览器。可以稍后继续这场对局。</p><div class="dialogactions">${btn('继续对局','close',false,'primary')}${btn('返回开始界面','new')}</div>`);return}if(type==='sound'){sound=!sound;tone();render();return}if(type==='export'){exportLog();return}if(type==='floor'){floor=Number(arg);render();return}if(type==='focus'){floor=game.roomNow.f;render();return}if(type==='trade'){const p=game.p,targets=game.s.players.filter(t=>t.alive&&t.id!==p.id&&t.room===p.room);openModal(`<h2>同房交换</h2><p>交出前请先征得对方同意；每件物品每回合只能进行一次物品动作。</p>${targets.length?p.items.filter(i=>i.type!=='omen').map(i=>`<p>${esc(i.name)} ${targets.map(t=>btn('交给 '+t.name,'give:'+i.id+':'+t.id,p.used.includes(i.id),'small')).join(' ')}</p>`).join(''):'<p>当前房间没有其他存活探索者。</p>'}<div class="dialogactions">${btn('返回','close')}</div>`);return}if(game.s.result||(game.s.mode==='solo'&&game.p.team==='traitor'))return;let before=game.s.active,ok=false;if(type==='move')ok=game.move(Number(arg));if(type==='room')ok=game.moveRoom(arg);if(type==='end')ok=game.endTurn();if(type==='task')ok=game.task(Number(arg));if(type==='attack')ok=game.attack(arg);if(type==='use')ok=game.use(arg);if(type==='pickup')ok=game.pickup();if(type==='give'){ok=game.trade(bits[0],Number(bits[1]));modal.close()}if(!ok){if(game.s.report)report();return}tone(type==='task'||type==='attack'?'dice':'move');floor=game.roomNow.f;persist();render();if(game.s.report&&!game.s.result)report();else if(game.s.mode==='local'&&before!==game.s.active&&!game.s.result)handoff();scheduleAI()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)act(el.dataset.action)});
document.addEventListener('keydown',e=>{if(modal.open||!game||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName))return;const key=e.key.toLowerCase(),map={w:0,arrowup:0,d:1,arrowright:1,s:2,arrowdown:2,a:3,arrowleft:3};if(key in map){e.preventDefault();act('move:'+map[key])}if(e.code==='Space'){e.preventDefault();act('end')}});
